Object.assign(translations.en,{downloadTemplate:'Download CSV Template',exportCsv:'Export CSV',clearFilters:'Clear Filters',matchingResults:'matching results',noMatches:'No results match the current filters',emptyLogins:'Upload a login log file or try the demo data',emptyVulns:'Upload a vulnerability report or try the demo data',emptyIncidents:'Open an incident or try the demo data',emptyPhishing:'Upload an .eml message or try the demo data',incidentSearch:'Search by incident ID or account…',loginSearch:'Search by account or IP address…',vulnSearch:'Search by device or CVE ID…',phishSearch:'Search by sender or subject…',suggestedLink:'Suggested Link',linkReason:'Same account, and the login event occurred 12 minutes after the phishing report.',confirmLink:'Confirm Link',dismissLink:'Dismiss Link',linkConfirmed:'Evidence link confirmed',linkDismissed:'Suggested link dismissed',decision:'Analyst decision',printSummary:'Print Incident Summary',safePreview:'Safe Message Preview',messageBody:'Message content',nonClickableLinks:'Non-clickable links',attachments:'Attachments',finalDecision:'Final decision',pendingDecision:'No decision recorded yet',attemptResult:'Attempt result',detectedAt:'Discovery date',remediatedAt:'Remediation date'});
