function pageSearchPlaceholder(page){return t()[{incidents:'incidentSearch',logins:'loginSearch',vulnerabilities:'vulnSearch',phishing:'phishSearch'}[page]]}
function pageEmptyMessage(page){return t()[{incidents:'emptyIncidents',logins:'emptyLogins',vulnerabilities:'emptyVulns',phishing:'emptyPhishing'}[page]]}
function filterOptions(page){return page==='incidents'?`<option value="all">${t().allStatuses}</option><option value="new">${t().newStatus}</option><option value="investigating">${t().investigating}</option><option value="closed">${t().closed}</option>`:`<option value="all">${t().allSeverities}</option><option value="high">${t().high}</option><option value="medium">${t().medium}</option><option value="low">${t().low}</option>`}
function sectionTemplate(page){if(!state.demo)return `<div class="hero"><div><h2>${t()[page]}</h2><p>${t()[{incidents:'incidentHelp',logins:'loginHelp',vulnerabilities:'vulnHelp',phishing:'phishHelp'}[page]]}</p></div></div><div class="panel contextual-empty"><div class="empty-icon">⌁</div><h2>${t().noData}</h2><p>${pageEmptyMessage(page)}</p><div class="empty-actions"><button class="primary-button section-action" data-action="${page}">${t()[{incidents:'newIncident',logins:'uploadCsv',vulnerabilities:'uploadReport',phishing:'uploadEml'}[page]]}</button><button class="secondary-button" id="emptyDemo">${t().tryDemo}</button></div></div>`;const action={incidents:'newIncident',logins:'uploadCsv',vulnerabilities:'uploadReport',phishing:'uploadEml'}[page];const rows=filtered(page);return `<div class="section-grid"><div class="panel"><div class="panel-header section-titlebar"><div><h2>${t()[page]}</h2><p>${t()[{incidents:'incidentHelp',logins:'loginHelp',vulnerabilities:'vulnHelp',phishing:'phishHelp'}[page]]}</p></div><div class="section-buttons"><button class="secondary-button export-button">${t().exportCsv}</button>${['logins','vulnerabilities'].includes(page)?`<button class="secondary-button template-button">${t().downloadTemplate}</button>`:''}<button class="primary-button section-action" data-action="${page}">${t()[action]}</button></div></div><div class="filter-row advanced-filter"><input id="searchInput" value="${state.search}" placeholder="${pageSearchPlaceholder(page)}" aria-label="${pageSearchPlaceholder(page)}"><select id="filterSelect">${filterOptions(page)}</select><button class="ghost-button" id="clearFilters">${t().clearFilters}</button></div><div class="results-count"><strong>${rows.length}</strong> ${t().matchingResults}</div>${rows.length?tableFor(page,rows):`<div class="no-results"><span>⌕</span><p>${t().noMatches}</p><button class="text-link" id="clearFiltersEmpty">${t().clearFilters}</button></div>`}</div>${actionCard(page)}</div>`}
