function exportCurrentResults(){const rows=filtered(state.page).map(row=>state.page==='incidents'?row.slice(0,5):row);const headers={incidents:['incident_id','title','severity','status','resolution_time'],logins:['account','time','reason','ip'],vulnerabilities:['device','cve_id','severity','status'],phishing:['sender','subject','signals','severity']}[state.page];const csv=[headers,...rows].map(row=>row.map(csvCell).join(',')).join('\n');downloadText(`${state.page}-filtered.csv`,csv)}
