function bindContent(){document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>navigate(b.dataset.card));['#tryDemo','#emptyDemo'].forEach(id=>{const el=$(id);if(el)el.onclick=loadDemo});document.querySelectorAll('.incident-link').forEach(b=>b.onclick=()=>{state.selectedIncident=b.dataset.incident;navigate('incident-detail')});document.querySelectorAll('.evidence-link').forEach(b=>b.onclick=()=>showEvidence(b.dataset.evidence));const search=$('#searchInput');if(search)search.oninput=e=>{state.search=e.target.value;document.querySelector('.table-wrap').outerHTML=tableFor(state.page,filtered(state.page));bindContent()};const filter=$('#filterSelect');if(filter){filter.value=state.filter;filter.onchange=e=>{state.filter=e.target.value;render()}}const action=$('.section-action');if(action)action.onclick=()=>{if(state.page==='incidents')showToast(t().incidentOpened);else configureAndOpenFile(state.page)};const ps=$('#periodSelect');if(ps)ps.onchange=e=>{state.period=e.target.value;persist();render()};['#dateFrom','#dateTo'].forEach(id=>{const input=$(id);if(input)input.onchange=()=>{state.customFrom=$('#dateFrom').value;state.customTo=$('#dateTo').value;requestAnimationFrame(drawCharts)}});const back=$('#backIncidents');if(back)back.onclick=()=>navigate('incidents');const save=$('#saveNotes');if(save)save.onclick=()=>{localStorage.setItem('tafaqqad-notes',$('#analystNotes').value);showToast(t().notesSaved)};const close=$('#closeIncident');if(close)close.onclick=()=>{state.incidentStatus='closed';data.incidents[0][3]='closed';persist();showToast(t().incidentClosed);render()}}
function drawCharts(){const scale=state.period==='30'?2:state.period==='custom'&&state.customFrom&&state.customTo?1.35:1;const adjust=rows=>rows.map(row=>row.map(v=>Math.round(v*scale)));drawLineChart($('#incidentChart'),adjust([[7,6,8,7,5,6,7],[1,2,1,3,2,4,3]]),['#8D3B1E','#487447']);drawLineChart($('#vulnChart'),adjust([[5,8,6,10,8,12,13],[2,3,4,4,6,7,8]]),['#8D3B1E','#487447'])}
function drawLineChart(canvas,series,colors){if(!canvas)return;const dpr=window.devicePixelRatio||1,w=canvas.clientWidth||500,h=220;canvas.width=w*dpr;canvas.height=h*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);ctx.strokeStyle='#dedcc8';ctx.lineWidth=1;for(let i=1;i<5;i++){ctx.beginPath();ctx.moveTo(30,i*38);ctx.lineTo(w-20,i*38);ctx.stroke()}series.forEach((vals,s)=>{ctx.strokeStyle=colors[s];ctx.lineWidth=3;ctx.beginPath();vals.forEach((v,i)=>{const x=30+i*(w-55)/(vals.length-1),y=190-v*11;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()})}
function showEvidence(type){const e=evidence[type];showModal(`<div class="modal-head"><div><small>${t().evidenceDetails}</small><h2 class="ltr">${e.title}</h2></div><button class="modal-close" aria-label="${t().cancel}">×</button></div>${e.reasonKey?`<div class="reason-callout"><b>${state.lang==='ar'?'سبب الاشتباه':'Suspicion reason'}</b><p>${t()[e.reasonKey]}</p></div>`:''}<h3>${t().rawRecords}</h3><div class="raw-records ltr">${e.records.map(r=>`<div>${r}</div>`).join('')}</div>`)}
function showModal(content){let wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<div class="modal" role="dialog" aria-modal="true">${content}</div>`;document.body.appendChild(wrap);const close=()=>wrap.remove();wrap.onclick=e=>{if(e.target===wrap||e.target.closest('.modal-close'))close()};document.addEventListener('keydown',function esc(e){if(e.key==='Escape'){close();document.removeEventListener('keydown',esc)}})}
function showImportPreview(file,page){const reader=new FileReader();reader.onload=()=>{const lines=String(reader.result).split(/\r?\n/).filter(Boolean);const parsed=lines.slice(0,5).map(x=>x.split(','));const expected=page==='logins'?['account','time','reason','ip']:['device','vulnerability','severity','status'];const headers=(parsed[0]||[]).map(x=>x.trim().toLowerCase());const missing=expected.filter(x=>!headers.includes(x));showModal(`<div class="modal-head"><div><small>${t().previewImport}</small><h2>${file.name}</h2></div><button class="modal-close">×</button></div><div class="missing-box"><b>${t().missingColumns}:</b> ${missing.length?missing.join(', '):t().noMissing}</div><h3>${t().previewRows}</h3><div class="table-wrap preview-table"><table>${parsed.map((row,i)=>`<tr>${row.map(c=>`<${i?'td':'th'}>${escapeHtml(c)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</table></div><div class="modal-actions"><button class="secondary-button modal-close">${t().cancel}</button><button class="primary-button" id="confirmImport">${t().confirmImport}</button></div>`);$('#confirmImport').onclick=()=>{document.querySelector('.modal-backdrop').remove();state.demo=true;persist();showImportSummary(Math.max(0,lines.length-2),1,missing.length?1:0);render()}};reader.readAsText(file)}
function showImportSummary(added,duplicates,unreadable){showModal(`<div class="modal-head"><h2>${t().importSummary}</h2><button class="modal-close">×</button></div><div class="import-stats"><article><strong>${added}</strong><span>${t().added}</span></article><article><strong>${duplicates}</strong><span>${t().duplicates}</span></article><article><strong>${unreadable}</strong><span>${t().unreadable}</span></article></div>`)}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
$('#fileInput').onchange=e=>{const file=e.target.files[0];if(!file)return;if(file.name.toLowerCase().endsWith('.csv'))showImportPreview(file,state.page);else{state.demo=true;persist();showToast(t().fileImported);render()}e.target.value=''};
render();
